 private async download(payload:GitHubPayload,kind:'assets'|'artifacts',prepareOnly=false):Promise<GitHubResponse>{const {realpath,stat}=await import('node:fs/promises');const root=await realpath(this.cwd),directory=await realpath(text(payload.values?.directory,'download folder',true));if(directory!==root&&!directory.startsWith(root+path.sep)||!(await stat(directory)).isDirectory())throw new Error('Choose a download folder inside the approved workspace');const names=payload.values?.names;if(names!==undefined&&(!Array.isArray(names)||names.length>100||names.some(value=>typeof value!=='string'||value.length>200||/[\0\r\n]/.test(value))))throw new Error('Choose at most 100 asset or artifact names');const repo=repository(payload.repository),hostRepo=`${this.context.getStore()||'github.com'}/${repo}`,id=numericId(payload.id);let argv:string[];
 if(kind==='artifacts'){argv=['run','download',`--repo=${hostRepo}`,`--dir=${directory}`,...(Array.isArray(names)?names.map(name=>`--name=${name}`):[]),'--',id];}else{const release=(await this.request('GET',`repos/${repo}/releases/${id}`)).data as {tag_name?:string};argv=['release','download',`--repo=${hostRepo}`,`--dir=${directory}`,'--skip-existing',...(Array.isArray(names)?names.map(name=>`--pattern=${name}`):[]),'--',text(release.tag_name,'release tag',true,200)];}if(prepareOnly)return {items:[],hasNext:false,page:0,detail:{prepared:{kind:'cli',argv}}};await this.cli(argv);return {items:[],hasNext:false,page:0,notice:`GitHub CLI downloaded the selected ${kind}. Existing release files are skipped; inspect the chosen local folder.`};}
